#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

// Variable global volatile para registrar cada activacion de la interrupcion
// Al ser volatile, el compilador no optimiza accesos y permite observarla en el depurador (Live Expressions/Watch)
// Debido a la oscilacion mecanica (rebote) del pulsador, con una sola pulsada fisica se incrementara varias veces
volatile uint32_t contador_pulsador = 0;

// Headers definitions
void init_gpio(void);
void init_exti(void);

int main(void)
{
    // Configurar el hardware antes de la funcion principal
    init_gpio();

    init_exti(); // Cargar la configuracion del EXTI para el pulsador PC13

    /* Loop forever */
    while (1) {
        // En espera de interrupciones
    }

    return 0;
}

void init_gpio(void)
{
    // Encender la señal de reloj para el GPIOA (LED verde LD2 en PA5)
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN_Msk;

    // Encender la señal de reloj para el GPIOC (Pulsador de usuario B1 en PC13)
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN_Msk;

    // --- Configuracion del PIN A5 como salida push-pull (LED verde) ---
    GPIOA->MODER &= ~(0b11 << GPIO_MODER_MODER5_Pos); // Limpiar la posicion
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODER5_Pos);  // Configuramos A5 como salida general

    GPIOA->OTYPER &= ~(1U << GPIO_OTYPER_OT5_Pos);    // Limpiamos la posicion, configuramos como salida push-pull

    GPIOA->OSPEEDR &= ~(0b11 << GPIO_OSPEEDR_OSPEED5_Pos); // Limpiamos la posicion
    GPIOA->OSPEEDR |= (0b01 << GPIO_OSPEEDR_OSPEED5_Pos);  // Configuramos velocidad media

    GPIOA->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD5_Pos);  // Sin resistencias pull-up / pull-down

    GPIOA->ODR &= ~GPIO_ODR_OD5; // LED verde apagado inicialmente

    // --- Configuracion del PIN C13 como entrada (Pulsador B1) ---
    GPIOC->MODER &= ~(0b11 << GPIO_MODER_MODER13_Pos); // Limpiar la posicion, modo entrada (00)

    // En la placa NUCLEO-F411RE el pulsador B1 ya cuenta con resistencia pull-up y filtro RC externos
    GPIOC->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD13_Pos);  // Sin pull-up ni pull-down interno
}

/*
Configuracion del EXTI para generar una interrupcion con el pulsador en PC13
*/
void init_exti(void)
{
    // 1. Encender la señal de reloj para el periferico SYSCFG (bus APB2)
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN_Msk;

    // 2. Mapear la linea EXTI13 al puerto GPIOC (PC13) en el multiplexor SYSCFG
    // EXTICR[3] corresponde al registro SYSCFG_EXTICR4 (lineas 12 a 15)
    SYSCFG->EXTICR[3] &= ~SYSCFG_EXTICR4_EXTI13_Msk; // Limpiar configuracion previa de la linea 13
    SYSCFG->EXTICR[3] |= SYSCFG_EXTICR4_EXTI13_PC;   // Seleccionar GPIOC para EXTI13

    // 3. Configurar el flanco de disparo
    // Al presionar el pulsador B1, la señal pasa de 3.3V a GND (flanco de bajada)
    EXTI->FTSR |= EXTI_FTSR_TR13;  // Habilitar deteccion por flanco de bajada
    EXTI->RTSR &= ~EXTI_RTSR_TR13; // Deshabilitar deteccion por flanco de subida

    // 4. Desenmascarar la interrupcion en la linea 13
    EXTI->IMR |= EXTI_IMR_MR13;

    // 5. Registrar y habilitar la interrupcion en el NVIC
    // Las lineas EXTI 10 a 15 comparten el vector EXTI15_10_IRQn
    NVIC_EnableIRQ(EXTI15_10_IRQn);
}

/*
ISR de EXTI15_10
Funcion que "administra" la interrupcion de las lineas EXTI 10 a 15
*/
void EXTI15_10_IRQHandler(void)
{
    // Verificar que la bandera de la linea 13 esta en alto
    if (EXTI->PR & EXTI_PR_PR13) {
        EXTI->PR = EXTI_PR_PR13; // Bajando la bandera de la interrupcion (se limpia escribiendo 1)

        // Incrementa la variable para evidenciar las oscilaciones/rebotes acumulados
        contador_pulsador++;

        // Hacemos "algo" en la interrupcion
        GPIOA->ODR ^= GPIO_ODR_OD5; // Hacemos un toogle en el LED verde (PA5)
    }
}
